import React from 'react';
import { InputBase, Paper, Stack } from '@mui/material';

export const OTP_LENGTH = 6;

export interface OtpInputBoxesProps {
    value: string;
    onChange: (next: string) => void;
    autoFocus?: boolean;
    disabled?: boolean;
}

/**
 * Six individual single-character inputs for the OTP code, with auto-advance
 * on type, backspace handling, and paste support.
 */
export const OtpInputBoxes: React.FC<OtpInputBoxesProps> = ({ value, onChange, autoFocus, disabled }) => {
    const refs = React.useRef<Array<HTMLInputElement | null>>([]);

    React.useEffect(() => {
        if (autoFocus) refs.current[0]?.focus();
    }, [autoFocus]);

    const setDigit = (index: number, digit: string) => {
        const sanitized = digit.replace(/\D/g, '');
        if (!sanitized) {
            const arr = value.padEnd(OTP_LENGTH, ' ').split('');
            arr[index] = '';
            onChange(arr.join('').replace(/\s+/g, ''));
            return;
        }
        const ch = sanitized[0];
        const arr = value.padEnd(OTP_LENGTH, ' ').split('');
        arr[index] = ch;
        const next = arr.join('').replace(/\s+/g, '').substring(0, OTP_LENGTH);
        onChange(next);
        if (index < OTP_LENGTH - 1) refs.current[index + 1]?.focus();
    };

    const handleKeyDown = (index: number) => (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Backspace') {
            const arr = value.padEnd(OTP_LENGTH, ' ').split('');
            if (arr[index] && arr[index] !== ' ') {
                arr[index] = '';
                onChange(arr.join('').replace(/\s+/g, ''));
            } else if (index > 0) {
                refs.current[index - 1]?.focus();
                arr[index - 1] = '';
                onChange(arr.join('').replace(/\s+/g, ''));
            }
        } else if (e.key === 'ArrowLeft' && index > 0) {
            refs.current[index - 1]?.focus();
        } else if (e.key === 'ArrowRight' && index < OTP_LENGTH - 1) {
            refs.current[index + 1]?.focus();
        }
    };

    const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
        e.preventDefault();
        const pasted = e.clipboardData.getData('text').replace(/\D/g, '').slice(0, OTP_LENGTH);
        if (pasted) {
            onChange(pasted);
            const focusIndex = Math.min(pasted.length, OTP_LENGTH - 1);
            refs.current[focusIndex]?.focus();
        }
    };

    return (
        <Stack
            direction='row'
            spacing={{ xs: 0.75, sm: 1.25 }}
            sx={{ justifyContent: 'center', width: '100%' }}
        >
            {Array.from({ length: OTP_LENGTH }).map((_, i) => (
                <Paper
                    key={i}
                    elevation={0}
                    variant='outlined'
                    sx={{
                        // Grow to share the available width but never shrink below a
                        // comfortable tap target — at 320px the fixed 38px boxes used to
                        // squeeze down to ~24px, which is far too small to hit reliably.
                        flex: '1 1 0',
                        minWidth: 36,
                        maxWidth: 48,
                        height: 48,
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        borderRadius: 2,
                        borderColor: value[i] ? 'primary.main' : 'divider',
                        bgcolor: 'background.paper',
                    }}
                >
                    <InputBase
                        inputRef={(el: HTMLInputElement | null) => { refs.current[i] = el; }}
                        value={value[i] ?? ''}
                        onChange={(e) => setDigit(i, e.target.value)}
                        onKeyDown={handleKeyDown(i)}
                        onPaste={handlePaste}
                        inputProps={{
                            inputMode: 'numeric',
                            pattern: '[0-9]*',
                            maxLength: 1,
                            // Lets iOS/Android offer the emailed code as a one-tap autofill
                            // suggestion instead of making the user switch apps to read it.
                            autoComplete: i === 0 ? 'one-time-code' : 'off',
                            'aria-label': `Digit ${i + 1}`,
                            style: {
                                textAlign: 'center',
                                fontSize: '1.25rem',
                                fontWeight: 600,
                                padding: 0,
                            },
                        }}
                        disabled={disabled}
                        sx={{ width: '100%', height: '100%' }}
                    />
                </Paper>
            ))}
        </Stack>
    );
};
